int tinydrm_enable_backlight ( struct backlight_device * backlight ) { unsigned int old_state ; int ret ; old_state = backlight -> props . state ; backlight -> props . state &= ~ BL_CORE_FBBLANK ; DRM_DEBUG_KMS ( "Backlight state: 0x%x ->0x%x\n" , old_state , backlight -> props . state ) ; ret = backlight_update_status ( backlight ) ; if ( ret ) { DRM_ERROR ( "Failed to enable backlight %d\n" , ret ) ; } return ret ; } 